 {current&&!editor&&<ProjectDetail p={current} mode={mode} projection={projection} tab={tab} setTab={setTab} onClose={closeProject} onEdit={()=>setEditor(structuredClone(current))} onDuplicate={()=>mutate('duplicate',async()=>{const d=await api({action:'duplicate',id:current.id});record(d.project);open(d.project);setEditor(structuredClone(d.project));setToast('Variante creata. L’originale resta disponibile.')})} onAssign={()=>setAssignOpen([current.id])} onFeedback={()=>setFeedbackProject(current)} progress={progress[current.id]||{projectId:current.id,checks:[],reflection:''}} onCheck={id=>check(current,id)} onReflection={v=>persistProgress({...progressRef.current[current.id]||{projectId:current.id,checks:[]},reflection:v})} onSaveProgress={()=>persistProgress(progressRef.current[current.id]||{projectId:current.id,checks:[],reflection:''})} busy={!!busy} saving={saving>0} history={historyData} historyLoading={historyLoading} onRestore={r=>{if(confirm('Ripristinare la revisione '+r.version+' come nuova revisione? Tutto lo storico sarà conservato.'))mutate('restore',async()=>{const d=await api({action:'restore',id:current.id,revisionId:r.id,expectedVersion:current.version});record(d.project);setToast('Ripristino salvato come nuova revisione.')})}} onOpenOriginal={()=>{const original=projects.find(p=>p.id===current.originalId);if(original)open(original,'docente')}} onArchive={()=>{if(confirm(current.archived?'Riportare il progetto nel catalogo?':'Archiviare il progetto? Potrai recuperarlo dalle revisioni.'))mutate('archive',async()=>{const d=await api({action:'archive',id:current.id,expectedVersion:current.version});record(d.project);closeProject();setToast(d.project.archived?'Progetto archiviato.':'Progetto ripristinato.')})}} allProjects={projects}/>} 
