 {assignOpen&&<AssignmentForm projects={visible} ids={assignOpen} busy={!!busy} onClose={()=>setAssignOpen(null)} onSubmit={a=>mutate('assign',async()=>{const d=await api({action:'assign',assignment:a});setAssignments(prev=>[d.assignment,...prev]);setAssignOpen(null);setToast('Assegnazione creata per '+a.className)})}/>}
