 {identityOpen&&<IdentityForm cloud={cloud} alias={alias} className={className} classes={Array.from(new Set(assignments.map(a=>a.className)))} onClose={()=>setIdentityOpen(false)} onSave={(a,c)=>{setAlias(a);setClassName(c);setIdentityOpen(false);setToast('Percorso aggiornato per '+a)}}/>}
